import { readFileSync } from "node:fs";
import type { Level, PrismaClient } from "../../generated/prisma/client";

// The course catalogue outline from brief section 4 (content/catalogue.json, generated by
// scripts/build-catalogue.py). It drives docs/CATALOGUE.md and, on request, draft course
// shells that admins fill with the company's own content.

export type CatalogueModule = { title: string; minutes: number; content: string };
export type CatalogueCourse = {
  title: string;
  description: string;
  objectives: string[];
  modules: CatalogueModule[];
  prerequisites: string[];
  existingCourse: string | null;
};
export type CatalogueSubject = {
  subject: string;
  category: "BUSINESS" | "TECHNICAL";
  learningPath: string;
  levels: Record<Level, CatalogueCourse>;
};
export type Catalogue = { note: string; subjects: CatalogueSubject[] };

export const LEVELS: Level[] = ["BASIC", "INTERMEDIATE", "ADVANCED"];
const LEVEL_NAME: Record<Level, string> = { BASIC: "Basic", INTERMEDIATE: "Intermediate", ADVANCED: "Advanced" };

export function loadCatalogue(path = "content/catalogue.json"): Catalogue {
  return JSON.parse(readFileSync(path, "utf8")) as Catalogue;
}

// Problems with the catalogue, empty when it is sound. `existing` lists the courses that
// already exist (subject, level, title), so links to them can be checked.
export function validateCatalogue(
  cat: Catalogue,
  subjectNames: string[],
  existing: { subject: string; level: Level; title: string }[],
): string[] {
  const problems: string[] = [];
  const names = cat.subjects.map((s) => s.subject);
  for (const n of subjectNames) if (!names.includes(n)) problems.push(`missing subject ${n}`);
  for (const s of cat.subjects) {
    if (!subjectNames.includes(s.subject)) problems.push(`unknown subject ${s.subject}`);
    for (const level of LEVELS) {
      const c = s.levels[level];
      const where = `${s.subject} ${level}`;
      if (!c) { problems.push(`${where}: no course`); continue; }
      if (c.objectives.length < 3 || c.objectives.length > 6) problems.push(`${where}: needs 3 to 6 objectives`);
      if (c.modules.length === 0) problems.push(`${where}: no modules`);
      for (const m of c.modules) {
        if (!(m.minutes > 0)) problems.push(`${where}: module "${m.title}" needs minutes`);
        if (!m.content.includes("[PLACEHOLDER")) problems.push(`${where}: module "${m.title}" must mark its content as a placeholder`);
      }
      const expected = level === "BASIC" ? [] : [s.levels[level === "ADVANCED" ? "INTERMEDIATE" : "BASIC"].title];
      if (JSON.stringify(c.prerequisites) !== JSON.stringify(expected)) problems.push(`${where}: prerequisite must be the level below`);
      if (c.existingCourse && !existing.some((e) => e.subject === s.subject && e.level === level && e.title === c.existingCourse)) {
        problems.push(`${where}: linked course "${c.existingCourse}" does not exist at this subject and level`);
      }
    }
  }
  return problems;
}

export function totalMinutes(c: CatalogueCourse): number {
  return c.modules.reduce((sum, m) => sum + m.minutes, 0);
}

const hours = (m: number) => (m >= 60 ? `${Math.floor(m / 60)} h${m % 60 ? ` ${m % 60} min` : ""}` : `${m} min`);

export function renderCatalogueMarkdown(cat: Catalogue): string {
  const out: string[] = [
    "# Course catalogue",
    "",
    "<!-- Generated from content/catalogue.json by `npm run catalogue:docs`. Do not edit by hand. -->",
    "",
    "The catalogue has 17 subjects, each with Basic, Intermediate and Advanced courses. Each level requires the level below it. Every module lists the content the company will supply and its expected format. Text marked [PLACEHOLDER] must be supplied or approved by the company; nothing here states company policy, prices or product claims.",
    "",
    "Courses marked \"in the portal\" already exist with sample content. The others can be created as draft course shells, with their modules, by running `npm run db:seed-catalogue`.",
    "",
    "Supported content formats: VIDEO (MP4 with WebVTT captions), PDF, TEXT, LINK, LAB (checklist) and LIVE_SESSION. SCORM packages are not supported yet (see open questions in ARCHITECTURE.md).",
    "",
    "## Subjects",
    "",
    ...cat.subjects.map((s) => `- [${s.subject}](#${slug(s.subject)}) (${s.category.toLowerCase()})`),
    "",
  ];
  for (const s of cat.subjects) {
    out.push(`## ${s.subject}`, "", `**Recommended learning path:** ${s.learningPath}`, "");
    for (const level of LEVELS) {
      const c = s.levels[level];
      out.push(`### ${c.title}`, "");
      out.push(c.description, "");
      out.push(`- **Level:** ${LEVEL_NAME[level]}`);
      out.push(`- **Estimated duration:** ${hours(totalMinutes(c))}`);
      out.push(`- **Prerequisites:** ${c.prerequisites.length ? c.prerequisites.join(", ") : "none"}`);
      out.push(`- **In the portal:** ${c.existingCourse ? `yes, as "${c.existingCourse}"` : "no, create with npm run db:seed-catalogue"}`);
      out.push("", "**Learning objectives**", "");
      for (const o of c.objectives) out.push(`- ${o}`);
      out.push("", "| # | Module | Time | Content to supply |", "| --- | --- | --- | --- |");
      c.modules.forEach((m, i) => out.push(`| ${i + 1} | ${m.title} | ${m.minutes} min | ${m.content} |`));
      out.push("");
    }
  }
  return out.join("\n");
}

function slug(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9 -]/g, "").replace(/ /g, "-");
}

// Creates a DRAFT course with its modules for every catalogue entry that is not already in
// the portal (by linked course or by title). Safe to run again. Returns how many were made.
export async function seedCatalogueDrafts(db: PrismaClient, cat: Catalogue): Promise<number> {
  let created = 0;
  for (const s of cat.subjects) {
    const subject = await db.subject.findUnique({ where: { name: s.subject } });
    if (!subject) throw new Error(`unknown subject ${s.subject}; run the main seed first`);
    for (const level of LEVELS) {
      const c = s.levels[level];
      if (c.existingCourse) continue;
      if (await db.course.findFirst({ where: { subjectId: subject.id, title: c.title } })) continue;
      const description = [
        c.description,
        `Objectives: ${c.objectives.join("; ")}.`,
        c.prerequisites.length ? `Prerequisite: ${c.prerequisites.join(", ")}.` : "",
      ].filter(Boolean).join(" ");
      await db.course.create({
        data: {
          subjectId: subject.id,
          title: c.title,
          description,
          level,
          status: "DRAFT",
          passMarkPercent: 70,
          modules: { create: c.modules.map((m, i) => ({ position: i + 1, title: m.title, estimatedMinutes: m.minutes })) },
        },
      });
      created++;
    }
  }
  return created;
}
